+     same numbers. Gesture suppression belongs here and on #gl, not on body. */
+  touch-action: none;
+  transition: opacity 0.35s ease, visibility 0s linear 0s;
+}
+/* Opacity alone left an invisible but fully live button cluster on the title,
+   dialogue, death and ending screens. */
+#hud.hidden {
+  opacity: 0;
+  pointer-events: none;
+  visibility: hidden;
+  transition: opacity 0.35s ease, visibility 0s linear 0.35s;
+}
+
+/* — vitals, top-left ------------------------------------------------------ */
+.vitals { position: absolute; top: calc(var(--pad) + var(--sa-t) + 2px); left: calc(var(--pad) + var(--sa-l)); width: calc(118px * var(--uiscale)); }
+
+.bar {
+  position: relative;
+  width: calc(100% - 30px * var(--uiscale));
+  height: calc(8px * var(--uiscale));
+  background: rgba(0, 0, 0, 0.6);
+  border: 1px solid rgba(58, 50, 38, 0.9);
+  border-radius: 2px;
+  margin-bottom: calc(3px * var(--uiscale));
+  /* The readout hangs outside the bar; an 8px box with a 1px border cannot
+     contain a legible glyph. */
+  overflow: visible;
+}
+.bar > .fill { position: absolute; inset: 0; transform-origin: left center; transition: transform 0.14s linear; border-radius: 1px; }
+/* Delayed "chip" layer drains behind the real value so hits read as damage. */
+.bar > .chip { position: absolute; inset: 0; transform-origin: left center; background: rgba(224, 120, 90, 0.42); transition: transform 0.5s ease 0.22s; border-radius: 1px; }
+.bar > .lbl {
+  position: absolute; left: calc(100% + 4px * var(--uiscale)); top: 50%; transform: translateY(-50%);
+  font-family: var(--ui-mono); font-variant-numeric: tabular-nums;
+  font-size: calc(9px * var(--uiscale)); line-height: 1;
+  color: rgba(255,255,255,0.92); letter-spacing: 0.02em;
+  text-shadow: 0 1px 2px #000, 0 0 4px #000;
+  white-space: nowrap;
+}
+.bar.hp   > .fill { background: linear-gradient(90deg, #8f2b23, #d8574a); }
+.bar.sta  > .fill { background: linear-gradient(90deg, #6d6320, #cbbc46); }
+
+/* Refused-for-stamina flash: the visible answer to a press that did nothing.
+   A silent refusal is exactly what makes a combat system feel like it is
+   ignoring you. */
+.bar.sta.empty { animation: staflash 0.42s steps(3) 1; }
+@keyframes staflash {
+  0%   { border-color: var(--blood); background: rgba(192, 57, 43, 0.55); }
+  100% { border-color: rgba(58, 50, 38, 0.9); background: rgba(0, 0, 0, 0.6); }
+}
+body.reduced .bar.sta.empty { animation: none; border-color: var(--blood); }
+.bar.hp.low > .fill { animation: pulse 0.85s ease-in-out infinite; }
+@keyframes pulse { 0%,100% { filter: brightness(1); } 50% { filter: brightness(1.7); } }
+
+/* — air gauge, the signature readout -------------------------------------- */
+.air {
+  margin-top: calc(4px * var(--uiscale));
+  border: 1px solid var(--line);
+  border-radius: var(--r);
+  background: rgba(10, 9, 8, 0.72);
+  padding: calc(3px * var(--uiscale)) calc(4px * var(--uiscale));
+}
+.air .row { display: flex; align-items: baseline; justify-content: space-between; }
+.air .ppm {
+  font-family: var(--ui-mono); font-size: calc(12px * var(--uiscale)); font-weight: 700;
+  letter-spacing: 0.02em; color: var(--bone); line-height: 1.1;
+}
+.air .unit { font-family: var(--ui-mono); font-size: calc(8px * var(--uiscale)); color: var(--bone-dim); letter-spacing: 0.08em; }
+.air .filter { font-family: var(--ui-mono); font-size: calc(8.5px * var(--uiscale)); color: var(--bone-dim); letter-spacing: 0.04em; margin-top: 1px; }
+.air.warn  { border-color: #8a7d1f; }
+.air.warn  .ppm { color: var(--toxic); }
+.air.crit  { border-color: var(--blood); animation: airpulse 0.7s steps(2) infinite; }
+.air.crit  .ppm { color: #ff6a5a; }
+.air { cursor: pointer; transition: border-color 0.18s linear; }
+.air.reading { border-color: var(--ember); }
+.air .trend {
+  font-family: var(--ui-mono); font-size: calc(8.5px * var(--uiscale)); color: var(--ember);
+  letter-spacing: 0.06em; opacity: 0; transition: opacity 0.25s linear; white-space: nowrap;
+}
+.air .trend.on { opacity: 1; }
+.air .reading {
+  font-family: var(--ui-mono); font-size: calc(9px * var(--uiscale)); color: var(--bone);
+  letter-spacing: 0.02em; margin-top: calc(2px * var(--uiscale)); line-height: 1.35;
+  max-height: 0; opacity: 0; overflow: hidden;
+  transition: max-height 0.22s ease-out, opacity 0.22s linear;
+}
+.air .reading.on { max-height: calc(48px * var(--uiscale)); opacity: 1; }
+@keyframes airpulse { 0% { background: rgba(120,20,14,0.42); } 100% { background: rgba(10,9,8,0.72); } }
+
+/* — compass strip, top-centre --------------------------------------------- */
+/* The compass sits above the objective. It used to sit 30px below the top,
+   which is exactly where a three-line objective lands, and the two overlapped
+   in every real frame. */
+.compass {
+  position: absolute; top: calc(var(--pad) + var(--sa-t)); left: 50%;
+  transform: translateX(-50%);
+  width: calc(160px * var(--uiscale)); height: calc(13px * var(--uiscale));
+  overflow: hidden;
+  /* A dark scrim: the ticks are 8.5px bone type and were invisible against
+     brick in the real frame. */
+  background: linear-gradient(90deg, transparent, rgba(6, 5, 4, 0.5) 20%, rgba(6, 5, 4, 0.5) 80%, transparent);
+  border-radius: 2px;
+  -webkit-mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
+  mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
+}
+.compass .tick {
+  position: absolute; top: calc(1px * var(--uiscale));
+  font-family: var(--ui-mono); font-size: calc(8.5px * var(--uiscale));
+  color: var(--bone); letter-spacing: 0.04em; transform: translateX(-50%);
+  text-shadow: 0 1px 2px #000, 0 0 4px #000;
+}
+.compass .mk  { position: absolute; top: calc(1px * var(--uiscale)); font-size: calc(9px * var(--uiscale)); transform: translateX(-50%); text-shadow: 0 1px 2px #000, 0 0 4px #000; }
+
+/* — objective, top-centre, under the compass ------------------------------ */
+.objective {
+  position: absolute;
+  top: calc(var(--pad) + var(--sa-t) + 16px * var(--uiscale));
+  left: 50%;
+  transform: translateX(-50%);
+  max-width: calc(190px * var(--uiscale));
+  text-align: center;
+  opacity: 0.94;
+}
+.objective .task { font-size: calc(10px * var(--uiscale)); color: var(--bone); line-height: 1.35; text-shadow: 0 1px 3px #000, 0 0 5px #000; }
+.objective .chapter { font-size: calc(8.5px * var(--uiscale)); letter-spacing: 0.2em; color: var(--ember); text-transform: uppercase; margin-bottom: 2px; text-shadow: 0 1px 3px #000; }
+
+/* — right-side stack: notices --------------------------------------------- */
+/* Below the system cluster, which now owns the top-right corner. */
+.notices {
+  position: absolute;
+  top: calc(var(--pad) + var(--sa-t) + 50px * var(--uiscale));
+  right: calc(var(--pad) + var(--sa-r));
+  width: calc(132px * var(--uiscale));
+  display: flex; flex-direction: column; align-items: flex-end; gap: calc(3px * var(--uiscale));
+}
+.notice {
+  background: rgba(12, 10, 8, 0.88);
+  border-right: 2px solid var(--ember);
+  border-radius: 2px;
+  padding: calc(4px * var(--uiscale)) calc(6px * var(--uiscale));
+  font-size: calc(10px * var(--uiscale));
+  color: var(--bone);
+  text-align: right;
+  line-height: 1.35;
+  animation: noticein 0.28s ease both;
+  max-width: 100%;
+}
+.notice b { color: var(--ember); font-weight: 600; }
+.notice.good { border-right-color: var(--toxic); }
+.notice.good b { color: var(--toxic); }
+.notice.bad  { border-right-color: var(--blood); }
+.notice.bad b { color: #ff8b7e; }
+.notice.fade { animation: noticeout 0.4s ease both; }
+@keyframes noticein  { from { opacity: 0; transform: translateX(14px); } to { opacity: 1; transform: none; } }
+@keyframes noticeout { to { opacity: 0; transform: translateX(14px); height: 0; padding-block: 0; margin-block: 0; } }
+
+/* ---------------------------------------------------------- touch input --- */
+
+.stick {
+  position: absolute;
+  bottom: calc(var(--pad) + var(--sa-b));
+  left: calc(var(--pad) + var(--sa-l));
+  width: calc(74px * var(--uiscale));
+  height: calc(74px * var(--uiscale));
+  border-radius: 50%;
+  border: 1px solid rgba(150, 138, 120, 0.34);
+  background: radial-gradient(circle at 50% 50%, rgba(30, 26, 20, 0.42), rgba(10, 9, 8, 0.2));
+  opacity: 0.55;
+  transition: opacity 0.18s ease;
+}
+.stick.active { opacity: 0.95; }
+.stick > .knob {
+  position: absolute; left: 50%; top: 50%;
+  width: calc(30px * var(--uiscale)); height: calc(30px * var(--uiscale));
+  margin: calc(-15px * var(--uiscale)) 0 0 calc(-15px * var(--uiscale));
+  border-radius: 50%;
+  background: radial-gradient(circle at 40% 35%, rgba(233, 224, 209, 0.62), rgba(120, 110, 96, 0.36));
+  border: 1px solid rgba(233, 224, 209, 0.42);
+  will-change: transform;
+}
+
+/* Right-hand action cluster. Thumb-arc layout, not a grid.
+   The container is a positioning frame only — it carries no `hit` class, so
+   the 54% of its rectangle that is not a button no longer swallows the camera
+   drag that a right thumb starts in this corner. Each .abtn opts in itself.
+   Every button is >=44pt and every pair is >=8pt apart (Apple HIG); the
+   geometry is verified in tools/_p_hud.mjs. */
+.actions {
+  --action-scale: max(1, var(--uiscale));
+  position: absolute;
+  right: calc(var(--pad) + var(--sa-r));
+  bottom: calc(var(--pad) + var(--sa-b));
+  width: calc(167px * var(--action-scale));
+  height: calc(134px * var(--action-scale));
+}
+.abtn {
+  position: absolute;
+  border-radius: 50%;
+  display: grid; place-items: center;
+  font-size: calc(8.5px * var(--uiscale));
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  font-weight: 700;
+  color: var(--bone);
+  background: rgba(28, 24, 18, 0.62);
+  border: 1px solid rgba(150, 138, 120, 0.4);
+  text-shadow: 0 1px 2px #000;
+  transition: transform 0.07s ease, background 0.1s ease, opacity 0.15s ease;
+  will-change: transform;
+}
+.abtn:active, .abtn.down { transform: scale(0.9); background: rgba(255, 122, 47, 0.42); border-color: var(--ember); }
+.abtn.engaged { background: rgba(255, 122, 47, 0.42); border: 2px solid var(--ember); }
+.abtn.engaged::after { content: '●'; position: absolute; bottom: 3px; font-size: 5px; }
+/* Unavailable: no stamina, nothing to use, cannot guard right now. Driven from
+   HUD.update — see _updateAvailability. */
+.abtn.dis { opacity: 0.3; border-color: rgba(150, 138, 120, 0.18); color: var(--dim); }
+
+.abtn.big  { width: calc(54px * var(--action-scale)); height: calc(54px * var(--action-scale)); font-size: calc(10px * var(--uiscale)); }
+.abtn.mid  { width: calc(44px * var(--action-scale)); height: calc(44px * var(--action-scale)); }
+.abtn.sml  { width: calc(44px * var(--action-scale)); height: calc(44px * var(--action-scale)); font-size: calc(8px * var(--uiscale)); }
+
+.abtn.attack   { right: calc(4px * var(--action-scale));   bottom: calc(6px * var(--action-scale)); }
+.abtn.dodge    { right: calc(68px * var(--action-scale));  bottom: calc(5px * var(--action-scale)); }
+.abtn.guard    { right: calc(7px * var(--action-scale));   bottom: calc(72px * var(--action-scale)); }
+.abtn.use      { right: calc(62px * var(--action-scale));  bottom: calc(70px * var(--action-scale)); }
+.abtn.heavy    { right: calc(120px * var(--action-scale)); bottom: calc(28px * var(--action-scale)); }
+/* Interact has its own slot. It used to be positioned on top of GUARD and
+   display:none the guard button underneath a possibly-held finger, which both
+   latched the input and removed the player's only defence next to a door. */
+.abtn.interact { right: calc(123px * var(--action-scale)); bottom: calc(90px * var(--action-scale));
+                 border-color: var(--ember); background: rgba(60, 34, 16, 0.72); }
+
+
+/* Context prompt (interact) floats above the action cluster. */
+.prompt {
+  position: absolute;
+  left: 50%; bottom: calc(var(--pad) + var(--sa-b) + 82px * var(--uiscale));
+  transform: translateX(-50%);
+  padding: calc(4px * var(--uiscale)) calc(9px * var(--uiscale));
+  background: rgba(10, 9, 8, 0.86);
+  border: 1px solid var(--line);
+  border-radius: 20px;
+  font-size: calc(10.5px * var(--uiscale));
+  color: var(--bone);
+  white-space: nowrap;
+  opacity: 0; transition: opacity 0.16s ease, transform 0.16s ease;
+}
+.prompt.on { opacity: 1; }
+.prompt b { color: var(--ember); font-weight: 700; }
+
+/* Top-right system buttons.
+   Each is a 44x44 target with a 30x30 visual plate drawn by the inner <i>, so
+   the row reads as light chrome while every button clears the HIG minimum. */
+.syscluster {
+  position: absolute;
+  top: calc(var(--pad) + var(--sa-t));
+  right: calc(var(--pad) + var(--sa-r));
+  display: flex; gap: calc(8px * var(--uiscale));
+}
+.sysbtn {
+  width: 44px; height: 44px;
+  display: grid; place-items: center;
+  background: none; border: 0;
+}
+.sysbtn > i {
+  width: calc(30px * var(--uiscale)); height: calc(30px * var(--uiscale));
+  display: grid; place-items: center;
+  border-radius: var(--r);
+  background: rgba(18, 15, 11, 0.78);
+  border: 1px solid var(--line);
+  font-style: normal;
+  font-size: calc(13px * var(--uiscale));
+  color: var(--bone-dim);
+  transition: background 0.1s ease, color 0.1s ease;
+}
+.sysbtn:active > i, .sysbtn.down > i { background: rgba(255, 122, 47, 0.34); border-color: var(--ember); color: var(--bone); }
+
+/* ------------------------------------------------------------ reticle ----- */
+
+.lockon {
+  position: absolute; width: 26px; height: 26px; margin: -13px 0 0 -13px;
+  border: 1px solid rgba(255, 122, 47, 0.85);
+  border-radius: 50%;
+  opacity: 0; transition: opacity 0.14s ease;
+  box-shadow: 0 0 10px rgba(255,122,47,0.5), inset 0 0 8px rgba(255,122,47,0.25);
+}
+.lockon.on { opacity: 1; }
+.lockon::before, .lockon::after {
+  content: ''; position: absolute; background: var(--ember);
+}
+.lockon::before { left: 50%; top: -5px; width: 1px; height: 4px; margin-left: -0.5px; }
+.lockon::after  { left: 50%; bottom: -5px; width: 1px; height: 4px; margin-left: -0.5px; }
+
+/* Enemy health pip above lock-on target */
+.enemybar {
+  position: absolute; width: calc(52px * var(--uiscale)); height: 3px; margin-left: calc(-26px * var(--uiscale));
+  background: rgba(0,0,0,0.72); border: 1px solid rgba(0,0,0,0.6); border-radius: 2px; overflow: hidden;
+  opacity: 0; transition: opacity 0.16s ease;
+}
+.enemybar.on { opacity: 1; }
+.enemybar > i { display: block; height: 100%; background: linear-gradient(90deg, #9a2a20, #e0655a); transform-origin: left; }
+/* Delayed chip. Driven with its own lagged value in HUD._updateLockOn — it was
+   previously assigned the same scale as the fill, which made it invisible. */
+.enemybar > u { position: absolute; inset: 0; display: block; background: rgba(255,220,180,0.55); transform-origin: left; transition: transform 0.45s ease 0.2s; }
+.enemybar.stagger > i { background: linear-gradient(90deg, #b58a1e, #e8cf5a); }
+
+/* Floating damage / status numbers */
+.fx-num {
+  position: absolute;
+  font-family: var(--ui-mono);
+  font-size: calc(11px * var(--uiscale));
+  font-weight: 700;
+  color: #fff;
+  text-shadow: 0 2px 4px #000, 0 0 8px rgba(255,120,60,0.5);
+  animation: fxnum 0.85s ease-out forwards;
+  will-change: transform, opacity;
+}
+.fx-num.crit { color: #ffcf7a; font-size: calc(14px * var(--uiscale)); }
+.fx-num.heal { color: var(--toxic); }
+.fx-num.self { color: #ff8b7e; }
+@keyframes fxnum {
+  0%   { opacity: 0; transform: translate(-50%, 0) scale(0.7); }
+  18%  { opacity: 1; transform: translate(-50%, -10px) scale(1.12); }
+  100% { opacity: 0; transform: translate(-50%, -34px) scale(0.95); }
+}
+
+/* Screen-space damage vignette */
+.hurt {
+  position: absolute; inset: 0;
+  background: radial-gradient(120% 90% at 50% 50%, transparent 42%, rgba(150, 26, 18, 0.62) 100%);
+  opacity: 0; transition: opacity 0.4s ease;
+}
+.hurt.on { opacity: 1; transition: opacity 0.06s ease; }
+
+/* Gas overlay — creeps in as CO saturation climbs */
+.gasveil {
+  position: absolute; inset: 0;
+  background:
+    radial-gradient(140% 110% at 50% 50%, transparent 28%, rgba(90, 88, 40, 0.5) 82%, rgba(40, 38, 16, 0.78) 100%);
+  opacity: 0;
+  transition: opacity 0.5s ease;
+}
+
+/* ------------------------------------------------------------- dialogue --- */
+
+/* The block is bottom-anchored and bounded by the viewport, and the choice
+   list takes whatever height is left over. That is what stops the list being
+   capped by a magic number that happened to be smaller than the content. */
+#dlg {
+  position: absolute;
+  left: 50%; bottom: calc(var(--pad) + var(--sa-b));
+  transform: translateX(-50%);
+  width: min(calc(100% - var(--sa-l) - var(--sa-r) - 16px), calc(430px * var(--uiscale)));
+  max-height: calc(100% - var(--sa-t) - var(--sa-b) - var(--pad) * 2);
+  display: none;
+  flex-direction: column;
+}
+#dlg.on { display: flex; }
+.dlg-box { flex: 0 0 auto; }
+
+.dlg-box {
+  background: linear-gradient(180deg, rgba(20, 17, 13, 0.965), rgba(10, 9, 7, 0.975));
+  border: 1px solid var(--line);
+  border-left: 2px solid var(--ember);
+  border-radius: var(--r);
+  padding: calc(7px * var(--uiscale)) calc(10px * var(--uiscale));
+}
+.dlg-who {
+  font-size: calc(9.5px * var(--uiscale));
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  color: var(--ember);
+  font-weight: 700;
+  margin-bottom: calc(3px * var(--uiscale));
+}
+.dlg-who .mood { color: var(--dim); letter-spacing: 0.06em; text-transform: none; font-weight: 400; font-style: italic; }
+.dlg-txt {
+  font-size: calc(10.5px * var(--uiscale));
+  line-height: 1.46;
+  color: var(--bone);
+  min-height: calc(2.9em);
+}
+.dlg-txt .caret { color: var(--ember); animation: blink 0.8s steps(2) infinite; }
+@keyframes blink { 0% { opacity: 1; } 50% { opacity: 0; } }
+
+.dlg-next {
+  text-align: right;
+  font-size: calc(9px * var(--uiscale));
+  color: var(--dim);
+  letter-spacing: 0.14em;
+  margin-top: calc(3px * var(--uiscale));
+}
+
+/* Choice list.
+   22 of the 27 choice nodes in the story have 3+ options and 4 have 5; at the
+   old 112px (84px on this device) the third option onwards could neither be
+   seen nor selected. The dialogue block is bottom-anchored, so growing this
+   grows upwards into empty screen. */
+.dlg-choicewrap {
+  position: relative;
+  margin-top: calc(4px * var(--uiscale));
+  flex: 0 1 auto; min-height: 0;
+  display: flex;
+}
+.dlg-choices { flex: 1 1 auto; min-height: 0; }
+/* Overflow affordance — a 6px scrollbar is not enough on its own. */
+.dlg-choicewrap::after {
+  content: '▾  MORE';
+  position: absolute; left: 0; right: 0; bottom: 0;
+  height: calc(20px * var(--uiscale));
+  display: grid; align-content: end; justify-items: center;
+  font-family: var(--ui-mono); font-size: calc(8.5px * var(--uiscale));
+  letter-spacing: 0.18em; color: var(--ember);
+  background: linear-gradient(180deg, rgba(8, 7, 6, 0) 0%, rgba(8, 7, 6, 0.94) 78%);
+  opacity: 0; transition: opacity 0.16s linear;
+  pointer-events: none;
+  border-radius: 0 0 var(--r) var(--r);
+}
+.dlg-choicewrap.more::after { opacity: 1; }
+.dlg-choice {
+  display: flex; flex-wrap: wrap; align-items: center;
+  min-height: 44px;
+  width: 100%; text-align: left;
+  background: rgba(38, 32, 24, 0.72);
+  border: 1px solid var(--line);
+  border-left: 2px solid var(--ember-lo);
+  border-radius: var(--r);
+  color: var(--bone);
+  font-family: var(--ui-sans);
+  font-size: calc(10px * var(--uiscale));
+  line-height: 1.36;
+  padding: calc(6px * var(--uiscale)) calc(9px * var(--uiscale));
+  margin-bottom: calc(3px * var(--uiscale));
+}
+.dlg-choice:active { background: rgba(255, 122, 47, 0.24); border-left-color: var(--ember); }
+.dlg-choice .tag {
+  display: inline-block;
+  flex: 0 0 auto;
+  font-family: var(--ui-mono);
+  font-size: calc(8.5px * var(--uiscale));
+  letter-spacing: 0.1em;
+  color: var(--ember);
+  border: 1px solid var(--ember-lo);
+  border-radius: 2px;
+  padding: 0 3px;
+  margin-right: 5px;
+  vertical-align: 1px;
+  text-transform: uppercase;
+}
+.dlg-choice .tag.locked { color: var(--dim); border-color: var(--line); }
+.dlg-choice.locked { opacity: 0.42; }
+.dlg-choice .why { flex: 1 0 100%; color: var(--dim); font-size: calc(9.5px * var(--uiscale)); margin-top: 2px; line-height: 1.3; }
+
+/* Speaker portrait strip — procedurally drawn to a canvas by the UI layer. */
+.dlg-port {
+  position: absolute; left: calc(-46px * var(--uiscale)); bottom: 0;
+  width: calc(42px * var(--uiscale)); height: calc(52px * var(--uiscale));
+  border: 1px solid var(--line); border-radius: var(--r);
+  background: #0b0a08; overflow: hidden;
+}
