+}
+.item .glyph.hit:active, .item .glyph.hit.on { background: rgba(255, 122, 47, 0.34); border-color: var(--ember); }
+.item .nm { font-size: calc(11px * var(--uiscale)); color: var(--bone); flex: 1 1 auto; line-height: 1.3; }
+.item .nm i { display: block; font-style: normal; color: var(--dim); font-size: calc(9.5px * var(--uiscale)); line-height: 1.35; }
+.item .qty { font-family: var(--ui-mono); font-size: calc(10.5px * var(--uiscale)); color: var(--ember); }
+
+/* Title screen */
+#title { display: none; position: absolute; inset: 0; z-index: 40; }
+#title.on { display: block; }
+.title-bg {
+  position: absolute; inset: 0;
+  /* Semi-opaque so the city is visible behind the mark — the title screen is
+     a photograph of Hollis with type over it, not a black plate. The scrim is
+     a readability gradient over the type only; the right two-thirds is left
+     nearly clear, and a burn glow is carried along the bottom edge so the
+     frame reads as a city over a fire even when the camera is parked low. */
+  background:
+    linear-gradient(90deg, rgba(6,5,4,0.90) 0%, rgba(6,5,4,0.66) 30%, rgba(6,5,4,0.12) 58%, rgba(6,5,4,0.10) 78%, rgba(6,5,4,0.58) 100%),
+    linear-gradient(0deg, rgba(58,24,6,0.62) 0%, rgba(28,13,4,0.28) 14%, rgba(0,0,0,0) 38%),
+    radial-gradient(120% 62% at 50% 104%, rgba(255,122,47,0.30) 0%, rgba(120,48,12,0.14) 40%, rgba(0,0,0,0) 72%),
+    radial-gradient(140% 120% at 50% 40%, rgba(0,0,0,0) 30%, rgba(4,3,2,0.72) 100%);
