+/* Mark bottom-left, menu filling the right column top to bottom: the empty
+   middle is the point of the frame, the empty corners were not. */
+.title-mark { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: flex-end; min-width: 0; }
+.title-mark h1 {
+  margin: 0;
+  font-size: calc(30px * var(--uiscale));
+  letter-spacing: 0.36em; text-indent: 0.36em;
+  font-weight: 300; color: var(--bone);
+  text-shadow: 0 0 40px rgba(255, 122, 47, 0.42), 0 3px 0 rgba(0,0,0,0.5);
+  line-height: 1;
+}
+.title-mark .rule-em {
+  height: 1px; width: calc(180px * var(--uiscale));
+  margin: calc(9px * var(--uiscale)) 0 calc(8px * var(--uiscale));
+  background: linear-gradient(90deg, var(--ember), rgba(255,122,47,0));
+}
+.title-mark .tagline {
+  font-size: calc(10.5px * var(--uiscale)); color: var(--bone-dim); letter-spacing: 0.08em; line-height: 1.6;
+  max-width: calc(270px * var(--uiscale));
+  text-shadow: 0 1px 4px #000;
+}
+.title-menu {
+  width: calc(180px * var(--uiscale)); flex: 0 0 auto;
+  display: flex; flex-direction: column; justify-content: center; gap: calc(2px * var(--uiscale));
+}
+
+/* Chapter / location card */
+.card {
+  position: absolute; left: 50%; top: 46%; transform: translate(-50%, -50%);
+  text-align: center; opacity: 0; pointer-events: none;
