+#ctxlost.on { display: grid; }
+#ctxlost .k { font-size: 15px; letter-spacing: 0.28em; color: var(--ember); font-weight: 600; }
+#ctxlost .s { font-size: 12px; color: var(--bone-dim); line-height: 1.6; margin: 10px 0 14px; max-width: 340px; }
