+   as broken in kana. Everything below is scoped so the English layout is
+   untouched.
+   ========================================================================== */
+
+html[data-lang="ja"] body,
+html[data-lang="ja"] .btn,
+html[data-lang="ja"] .sub,
+html[data-lang="ja"] .dlg-txt {
+  /* Break anywhere a Japanese line legally can, and never mid-punctuation. */
