+html[data-lang="ja"] .sub      { font-size: calc(11.5px * var(--uiscale)); line-height: 1.78; }
+html[data-lang="ja"] .btn      { font-size: calc(12px * var(--uiscale)); }
+html[data-lang="ja"] .dlg-choice { font-size: calc(11px * var(--uiscale)); line-height: 1.5; }
+html[data-lang="ja"] .notice   { font-size: calc(11px * var(--uiscale)); line-height: 1.5; }
+html[data-lang="ja"] .item .nm { font-size: calc(11.5px * var(--uiscale)); }
