+  /** Pink-ish noise (Voss-McCartney, 5 rows). Ambience wants pink, not white. */
+  _makePink(seconds) {
+    const ctx = this.ctx;
+    const n = Math.floor(ctx.sampleRate * seconds);
+    const buf = ctx.createBuffer(1, n, ctx.sampleRate);
