+   geometry is verified in tools/_p_hud.mjs. */
+.actions {
+  --action-scale: max(1, var(--uiscale));
+  position: absolute;
+  right: calc(var(--pad) + var(--sa-r));
+  bottom: calc(var(--pad) + var(--sa-b));
+  width: calc(167px * var(--action-scale));
+  height: calc(134px * var(--action-scale));
+}
+.abtn {
+  position: absolute;
+  border-radius: 50%;
+  display: grid; place-items: center;
+  font-size: calc(8.5px * var(--uiscale));
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  font-weight: 700;
+  color: var(--bone);
+  background: rgba(28, 24, 18, 0.62);
+  border: 1px solid rgba(150, 138, 120, 0.4);
+  text-shadow: 0 1px 2px #000;
+  transition: transform 0.07s ease, background 0.1s ease, opacity 0.15s ease;
+  will-change: transform;
+}
+.abtn:active, .abtn.down { transform: scale(0.9); background: rgba(255, 122, 47, 0.42); border-color: var(--ember); }
+.abtn.engaged { background: rgba(255, 122, 47, 0.42); border: 2px solid var(--ember); }
+.abtn.engaged::after { content: '●'; position: absolute; bottom: 3px; font-size: 5px; }
+/* Unavailable: no stamina, nothing to use, cannot guard right now. Driven from
+   HUD.update — see _updateAvailability. */
+.abtn.dis { opacity: 0.3; border-color: rgba(150, 138, 120, 0.18); color: var(--dim); }
+
+.abtn.big  { width: calc(54px * var(--action-scale)); height: calc(54px * var(--action-scale)); font-size: calc(10px * var(--uiscale)); }
+.abtn.mid  { width: calc(44px * var(--action-scale)); height: calc(44px * var(--action-scale)); }
+.abtn.sml  { width: calc(44px * var(--action-scale)); height: calc(44px * var(--action-scale)); font-size: calc(8px * var(--uiscale)); }
+
+.abtn.attack   { right: calc(4px * var(--action-scale));   bottom: calc(6px * var(--action-scale)); }
+.abtn.dodge    { right: calc(68px * var(--action-scale));  bottom: calc(5px * var(--action-scale)); }
+.abtn.guard    { right: calc(7px * var(--action-scale));   bottom: calc(72px * var(--action-scale)); }
+.abtn.use      { right: calc(62px * var(--action-scale));  bottom: calc(70px * var(--action-scale)); }
+.abtn.heavy    { right: calc(120px * var(--action-scale)); bottom: calc(28px * var(--action-scale)); }
+/* Interact has its own slot. It used to be positioned on top of GUARD and
+   display:none the guard button underneath a possibly-held finger, which both
+   latched the input and removed the player's only defence next to a door. */
+.abtn.interact { right: calc(123px * var(--action-scale)); bottom: calc(90px * var(--action-scale));
+                 border-color: var(--ember); background: rgba(60, 34, 16, 0.72); }
+
+
+/* Context prompt (interact) floats above the action cluster. */
+.prompt {
+  position: absolute;
+  left: 50%; bottom: calc(var(--pad) + var(--sa-b) + 82px * var(--uiscale));
+  transform: translateX(-50%);
+  padding: calc(4px * var(--uiscale)) calc(9px * var(--uiscale));
+  background: rgba(10, 9, 8, 0.86);
+  border: 1px solid var(--line);
+  border-radius: 20px;
+  font-size: calc(10.5px * var(--uiscale));
+  color: var(--bone);
+  white-space: nowrap;
+  opacity: 0; transition: opacity 0.16s ease, transform 0.16s ease;
+}
+.prompt.on { opacity: 1; }
+.prompt b { color: var(--ember); font-weight: 700; }
+
+/* Top-right system buttons.
+   Each is a 44x44 target with a 30x30 visual plate drawn by the inner <i>, so
+   the row reads as light chrome while every button clears the HIG minimum. */
+.syscluster {
+  position: absolute;
+  top: calc(var(--pad) + var(--sa-t));
+  right: calc(var(--pad) + var(--sa-r));
+  display: flex; gap: calc(8px * var(--uiscale));
+}
+.sysbtn {
+  width: 44px; height: 44px;
+  display: grid; place-items: center;
+  background: none; border: 0;
+}
+.sysbtn > i {
+  width: calc(30px * var(--uiscale)); height: calc(30px * var(--uiscale));
+  display: grid; place-items: center;
+  border-radius: var(--r);
+  background: rgba(18, 15, 11, 0.78);
+  border: 1px solid var(--line);
+  font-style: normal;
+  font-size: calc(13px * var(--uiscale));
+  color: var(--bone-dim);
+  transition: background 0.1s ease, color 0.1s ease;
+}
+.sysbtn:active > i, .sysbtn.down > i { background: rgba(255, 122, 47, 0.34); border-color: var(--ember); color: var(--bone); }
+
+/* ------------------------------------------------------------ reticle ----- */
+
+.lockon {
+  position: absolute; width: 26px; height: 26px; margin: -13px 0 0 -13px;
+  border: 1px solid rgba(255, 122, 47, 0.85);
+  border-radius: 50%;
+  opacity: 0; transition: opacity 0.14s ease;
+  box-shadow: 0 0 10px rgba(255,122,47,0.5), inset 0 0 8px rgba(255,122,47,0.25);
+}
+.lockon.on { opacity: 1; }
+.lockon::before, .lockon::after {
+  content: ''; position: absolute; background: var(--ember);
+}
+.lockon::before { left: 50%; top: -5px; width: 1px; height: 4px; margin-left: -0.5px; }
+.lockon::after  { left: 50%; bottom: -5px; width: 1px; height: 4px; margin-left: -0.5px; }
+
+/* Enemy health pip above lock-on target */
+.enemybar {
+  position: absolute; width: calc(52px * var(--uiscale)); height: 3px; margin-left: calc(-26px * var(--uiscale));
+  background: rgba(0,0,0,0.72); border: 1px solid rgba(0,0,0,0.6); border-radius: 2px; overflow: hidden;
+  opacity: 0; transition: opacity 0.16s ease;
+}
+.enemybar.on { opacity: 1; }
+.enemybar > i { display: block; height: 100%; background: linear-gradient(90deg, #9a2a20, #e0655a); transform-origin: left; }
+/* Delayed chip. Driven with its own lagged value in HUD._updateLockOn — it was
+   previously assigned the same scale as the fill, which made it invisible. */
+.enemybar > u { position: absolute; inset: 0; display: block; background: rgba(255,220,180,0.55); transform-origin: left; transition: transform 0.45s ease 0.2s; }
+.enemybar.stagger > i { background: linear-gradient(90deg, #b58a1e, #e8cf5a); }
+
+/* Floating damage / status numbers */
+.fx-num {
+  position: absolute;
+  font-family: var(--ui-mono);
+  font-size: calc(11px * var(--uiscale));
+  font-weight: 700;
+  color: #fff;
+  text-shadow: 0 2px 4px #000, 0 0 8px rgba(255,120,60,0.5);
+  animation: fxnum 0.85s ease-out forwards;
+  will-change: transform, opacity;
+}
+.fx-num.crit { color: #ffcf7a; font-size: calc(14px * var(--uiscale)); }
+.fx-num.heal { color: var(--toxic); }
+.fx-num.self { color: #ff8b7e; }
+@keyframes fxnum {
+  0%   { opacity: 0; transform: translate(-50%, 0) scale(0.7); }
+  18%  { opacity: 1; transform: translate(-50%, -10px) scale(1.12); }
+  100% { opacity: 0; transform: translate(-50%, -34px) scale(0.95); }
+}
+
+/* Screen-space damage vignette */
+.hurt {
+  position: absolute; inset: 0;
+  background: radial-gradient(120% 90% at 50% 50%, transparent 42%, rgba(150, 26, 18, 0.62) 100%);
+  opacity: 0; transition: opacity 0.4s ease;
+}
+.hurt.on { opacity: 1; transition: opacity 0.06s ease; }
+
+/* Gas overlay — creeps in as CO saturation climbs */
+.gasveil {
+  position: absolute; inset: 0;
+  background:
+    radial-gradient(140% 110% at 50% 50%, transparent 28%, rgba(90, 88, 40, 0.5) 82%, rgba(40, 38, 16, 0.78) 100%);
+  opacity: 0;
+  transition: opacity 0.5s ease;
+}
+
+/* ------------------------------------------------------------- dialogue --- */
+
+/* The block is bottom-anchored and bounded by the viewport, and the choice
+   list takes whatever height is left over. That is what stops the list being
+   capped by a magic number that happened to be smaller than the content. */
+#dlg {
+  position: absolute;
+  left: 50%; bottom: calc(var(--pad) + var(--sa-b));
+  transform: translateX(-50%);
+  width: min(calc(100% - var(--sa-l) - var(--sa-r) - 16px), calc(430px * var(--uiscale)));
+  max-height: calc(100% - var(--sa-t) - var(--sa-b) - var(--pad) * 2);
+  display: none;
+  flex-direction: column;
+}
+#dlg.on { display: flex; }
+.dlg-box { flex: 0 0 auto; }
+
+.dlg-box {
+  background: linear-gradient(180deg, rgba(20, 17, 13, 0.965), rgba(10, 9, 7, 0.975));
+  border: 1px solid var(--line);
+  border-left: 2px solid var(--ember);
+  border-radius: var(--r);
+  padding: calc(7px * var(--uiscale)) calc(10px * var(--uiscale));
+}
+.dlg-who {
+  font-size: calc(9.5px * var(--uiscale));
+  letter-spacing: 0.2em;
+  text-transform: uppercase;
+  color: var(--ember);
+  font-weight: 700;
+  margin-bottom: calc(3px * var(--uiscale));
+}
+.dlg-who .mood { color: var(--dim); letter-spacing: 0.06em; text-transform: none; font-weight: 400; font-style: italic; }
+.dlg-txt {
+  font-size: calc(10.5px * var(--uiscale));
+  line-height: 1.46;
+  color: var(--bone);
+  min-height: calc(2.9em);
+}
+.dlg-txt .caret { color: var(--ember); animation: blink 0.8s steps(2) infinite; }
+@keyframes blink { 0% { opacity: 1; } 50% { opacity: 0; } }
+
+.dlg-next {
+  text-align: right;
+  font-size: calc(9px * var(--uiscale));
+  color: var(--dim);
+  letter-spacing: 0.14em;
+  margin-top: calc(3px * var(--uiscale));
+}
+
+/* Choice list.
+   22 of the 27 choice nodes in the story have 3+ options and 4 have 5; at the
+   old 112px (84px on this device) the third option onwards could neither be
+   seen nor selected. The dialogue block is bottom-anchored, so growing this
+   grows upwards into empty screen. */
+.dlg-choicewrap {
+  position: relative;
+  margin-top: calc(4px * var(--uiscale));
+  flex: 0 1 auto; min-height: 0;
+  display: flex;
+}
+.dlg-choices { flex: 1 1 auto; min-height: 0; }
+/* Overflow affordance — a 6px scrollbar is not enough on its own. */
+.dlg-choicewrap::after {
+  content: '▾  MORE';
+  position: absolute; left: 0; right: 0; bottom: 0;
+  height: calc(20px * var(--uiscale));
+  display: grid; align-content: end; justify-items: center;
+  font-family: var(--ui-mono); font-size: calc(8.5px * var(--uiscale));
+  letter-spacing: 0.18em; color: var(--ember);
+  background: linear-gradient(180deg, rgba(8, 7, 6, 0) 0%, rgba(8, 7, 6, 0.94) 78%);
+  opacity: 0; transition: opacity 0.16s linear;
+  pointer-events: none;
+  border-radius: 0 0 var(--r) var(--r);
+}
+.dlg-choicewrap.more::after { opacity: 1; }
+.dlg-choice {
+  display: flex; flex-wrap: wrap; align-items: center;
+  min-height: 44px;
+  width: 100%; text-align: left;
+  background: rgba(38, 32, 24, 0.72);
+  border: 1px solid var(--line);
+  border-left: 2px solid var(--ember-lo);
+  border-radius: var(--r);
+  color: var(--bone);
+  font-family: var(--ui-sans);
+  font-size: calc(10px * var(--uiscale));
+  line-height: 1.36;
+  padding: calc(6px * var(--uiscale)) calc(9px * var(--uiscale));
+  margin-bottom: calc(3px * var(--uiscale));
+}
+.dlg-choice:active { background: rgba(255, 122, 47, 0.24); border-left-color: var(--ember); }
+.dlg-choice .tag {
+  display: inline-block;
+  flex: 0 0 auto;
+  font-family: var(--ui-mono);
+  font-size: calc(8.5px * var(--uiscale));
+  letter-spacing: 0.1em;
+  color: var(--ember);
+  border: 1px solid var(--ember-lo);
+  border-radius: 2px;
+  padding: 0 3px;
+  margin-right: 5px;
+  vertical-align: 1px;
+  text-transform: uppercase;
+}
+.dlg-choice .tag.locked { color: var(--dim); border-color: var(--line); }
+.dlg-choice.locked { opacity: 0.42; }
+.dlg-choice .why { flex: 1 0 100%; color: var(--dim); font-size: calc(9.5px * var(--uiscale)); margin-top: 2px; line-height: 1.3; }
+
+/* Speaker portrait strip — procedurally drawn to a canvas by the UI layer. */
+.dlg-port {
+  position: absolute; left: calc(-46px * var(--uiscale)); bottom: 0;
+  width: calc(42px * var(--uiscale)); height: calc(52px * var(--uiscale));
+  border: 1px solid var(--line); border-radius: var(--r);
+  background: #0b0a08; overflow: hidden;
+}
+.dlg-port canvas { width: 100%; height: 100%; display: block; }
+@media (max-width: 620px) { .dlg-port { display: none; } }
+
+/* --------------------------------------------------------------- menus ---- */
+
+.screen {
+  position: absolute; inset: 0;
+  /* Above #title (40). Settings opened from the title screen used to render
+     underneath it, so the title's own menu column sat on top of the settings
+     list and ate taps meant for the rows behind it. */
+  z-index: 45;
+  display: none;
+  background: rgba(6, 5, 4, 0.86);
+  backdrop-filter: blur(2px);
+  -webkit-backdrop-filter: blur(2px);
+  padding: calc(var(--pad) + var(--sa-t)) calc(var(--pad) + var(--sa-r))
+           calc(var(--pad) + var(--sa-b)) calc(var(--pad) + var(--sa-l));
+}
+.screen.on { display: block; }
+/* The epilogue must outrank #fade (z-index 60). finish() fades out and shows
+   the ending; if any caller ever forgets the matching fadeIn, the payoff of
+   the whole game must not end up under an opaque black plate. */
+.screen.ending { z-index: 70; }
+
+.screen-inner {
+  position: absolute;
+  inset: calc(var(--pad) + var(--sa-t)) calc(var(--pad) + var(--sa-r))
+         calc(var(--pad) + var(--sa-b)) calc(var(--pad) + var(--sa-l));
+  display: flex; flex-direction: column;
+}
+
+.screen-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: calc(5px * var(--uiscale)); flex: 0 0 auto; }
+.screen-title { font-size: calc(11px * var(--uiscale)); letter-spacing: 0.3em; text-transform: uppercase; color: var(--bone); font-weight: 600; }
+.screen-body { flex: 1 1 auto; min-height: 0; display: flex; gap: calc(8px * var(--uiscale)); }
+
+.col { min-height: 0; display: flex; flex-direction: column; }
+.col.main { flex: 1 1 auto; }
+
+.tabs { display: flex; gap: calc(3px * var(--uiscale)); margin-bottom: calc(5px * var(--uiscale)); flex-wrap: wrap; }
+.tab {
+  display: grid; place-items: center;
+  min-height: 44px;
+  font-size: calc(9.5px * var(--uiscale));
+  letter-spacing: 0.12em; text-transform: uppercase;
+  padding: 0 calc(9px * var(--uiscale));
+  border: 1px solid var(--line); border-radius: var(--r);
+  color: var(--dim); background: rgba(20, 17, 13, 0.6);
+}
+.tab.on { color: var(--ink); background: var(--ember); border-color: var(--ember); font-weight: 700; }
+
+.close {
+  width: 44px; height: 44px;
+  border: 1px solid var(--line); border-radius: var(--r);
+  display: grid; place-items: center; color: var(--bone-dim); font-size: calc(15px * var(--uiscale));
+  background: rgba(20, 17, 13, 0.7);
+}
+.close:active, .close.on { background: var(--blood); color: #fff; }
+
+/* item rows */
+.item {
+  display: flex; align-items: center; gap: calc(8px * var(--uiscale));
+  min-height: 44px;
+  padding: calc(5px * var(--uiscale)) calc(6px * var(--uiscale));
+  border: 1px solid transparent; border-bottom-color: rgba(58,50,38,0.5);
+  border-radius: var(--r);
+}
+.item.on { background: rgba(255, 122, 47, 0.14); border-color: var(--ember-lo); }
+.item .glyph {
+  width: calc(22px * var(--uiscale)); height: calc(22px * var(--uiscale)); flex: 0 0 auto;
+  border: 1px solid var(--line); border-radius: 2px; background: #0d0b09;
+  display: grid; place-items: center; font-size: calc(11px * var(--uiscale));
+}
+/* Only the slider steppers carry `hit`; they are real buttons and get a real
+   target. The decorative row glyphs stay 22px. */
+.item .glyph.hit {
+  width: 44px; height: 44px;
+  font-size: calc(15px * var(--uiscale));
+  background: rgba(30, 26, 20, 0.8);
+  color: var(--bone);
+}
+.item .glyph.hit:active, .item .glyph.hit.on { background: rgba(255, 122, 47, 0.34); border-color: var(--ember); }
+.item .nm { font-size: calc(11px * var(--uiscale)); color: var(--bone); flex: 1 1 auto; line-height: 1.3; }
+.item .nm i { display: block; font-style: normal; color: var(--dim); font-size: calc(9.5px * var(--uiscale)); line-height: 1.35; }
+.item .qty { font-family: var(--ui-mono); font-size: calc(10.5px * var(--uiscale)); color: var(--ember); }
+
+/* Title screen */
+#title { display: none; position: absolute; inset: 0; z-index: 40; }
+#title.on { display: block; }
+.title-bg {
+  position: absolute; inset: 0;
+  /* Semi-opaque so the city is visible behind the mark — the title screen is
+     a photograph of Hollis with type over it, not a black plate. The scrim is
+     a readability gradient over the type only; the right two-thirds is left
+     nearly clear, and a burn glow is carried along the bottom edge so the
+     frame reads as a city over a fire even when the camera is parked low. */
+  background:
+    linear-gradient(90deg, rgba(6,5,4,0.90) 0%, rgba(6,5,4,0.66) 30%, rgba(6,5,4,0.12) 58%, rgba(6,5,4,0.10) 78%, rgba(6,5,4,0.58) 100%),
+    linear-gradient(0deg, rgba(58,24,6,0.62) 0%, rgba(28,13,4,0.28) 14%, rgba(0,0,0,0) 38%),
+    radial-gradient(120% 62% at 50% 104%, rgba(255,122,47,0.30) 0%, rgba(120,48,12,0.14) 40%, rgba(0,0,0,0) 72%),
+    radial-gradient(140% 120% at 50% 40%, rgba(0,0,0,0) 30%, rgba(4,3,2,0.72) 100%);
+}
+.title-wrap {
+  position: absolute; inset: 0;
+  padding: calc(var(--pad) + var(--sa-t) + 6px) calc(var(--pad) + var(--sa-r)) calc(var(--pad) + var(--sa-b) + 6px) calc(var(--pad) + var(--sa-l) + 6px);
+  display: flex; align-items: stretch; justify-content: space-between; gap: calc(12px * var(--uiscale));
+}
+/* Mark bottom-left, menu filling the right column top to bottom: the empty
+   middle is the point of the frame, the empty corners were not. */
+.title-mark { flex: 1 1 auto; display: flex; flex-direction: column; justify-content: flex-end; min-width: 0; }
+.title-mark h1 {
+  margin: 0;
+  font-size: calc(30px * var(--uiscale));
+  letter-spacing: 0.36em; text-indent: 0.36em;
+  font-weight: 300; color: var(--bone);
+  text-shadow: 0 0 40px rgba(255, 122, 47, 0.42), 0 3px 0 rgba(0,0,0,0.5);
+  line-height: 1;
+}
+.title-mark .rule-em {
+  height: 1px; width: calc(180px * var(--uiscale));
+  margin: calc(9px * var(--uiscale)) 0 calc(8px * var(--uiscale));
+  background: linear-gradient(90deg, var(--ember), rgba(255,122,47,0));
+}
+.title-mark .tagline {
+  font-size: calc(10.5px * var(--uiscale)); color: var(--bone-dim); letter-spacing: 0.08em; line-height: 1.6;
+  max-width: calc(270px * var(--uiscale));
+  text-shadow: 0 1px 4px #000;
+}
+.title-menu {
+  width: calc(180px * var(--uiscale)); flex: 0 0 auto;
+  display: flex; flex-direction: column; justify-content: center; gap: calc(2px * var(--uiscale));
+}
+
+/* Chapter / location card */
+.card {
+  position: absolute; left: 50%; top: 46%; transform: translate(-50%, -50%);
+  text-align: center; opacity: 0; pointer-events: none;
+}
+.card.on { animation: cardin 4.6s ease both; }
+.card .k { font-size: calc(8px * var(--uiscale)); letter-spacing: 0.42em; color: var(--ember); text-transform: uppercase; }
+.card .t { font-size: calc(19px * var(--uiscale)); letter-spacing: 0.14em; color: var(--bone); font-weight: 300; margin-top: calc(5px * var(--uiscale)); text-shadow: 0 2px 20px #000; }
+.card .s { font-size: calc(8.5px * var(--uiscale)); color: var(--bone-dim); margin-top: calc(5px * var(--uiscale)); letter-spacing: 0.08em; }
+@keyframes cardin {
+  0%   { opacity: 0; transform: translate(-50%, -50%) scale(1.06); letter-spacing: 0.2em; }
+  14%  { opacity: 1; transform: translate(-50%, -50%) scale(1); }
+  80%  { opacity: 1; }
+  100% { opacity: 0; }
+}
+
+/* Fade-to-black transition plate */
+#fade { position: absolute; inset: 0; background: #000; opacity: 0; pointer-events: none; transition: opacity 0.6s ease; z-index: 60; }
+#fade.on { opacity: 1; }
+#fade.slow { transition-duration: 1.8s; }
+
+/* Death / retry */
+.dead { position: absolute; inset: 0; display: none; place-items: center; background: rgba(10, 3, 2, 0.86); z-index: 50; }
+.dead.on { display: grid; }
+.dead-inner { text-align: center; width: min(78vw, calc(300px * var(--uiscale))); }
+.dead-inner .k { font-size: calc(17px * var(--uiscale)); letter-spacing: 0.34em; color: #d4483a; font-weight: 300; }
+.dead-inner .s { font-size: calc(10.5px * var(--uiscale)); color: var(--bone-dim); margin: calc(7px * var(--uiscale)) 0 calc(10px * var(--uiscale)); line-height: 1.6; font-style: italic; }
+
+/* Subtitles / barks — clear of the (taller) action cluster. */
+.subs {
+  position: absolute; left: 50%; bottom: calc(var(--pad) + var(--sa-b) + 142px * var(--uiscale));
+  transform: translateX(-50%);
+  width: min(calc(100% - 30px), calc(340px * var(--uiscale)));
+  text-align: center;
+  font-size: calc(10.5px * var(--uiscale));
+  color: var(--bone);
+  text-shadow: 0 1px 4px #000, 0 0 10px #000;
+  line-height: 1.4;
+  pointer-events: none;
+}
+.subs .spk { color: var(--ember); font-weight: 700; letter-spacing: 0.06em; }
