+  /** Generic percussive impact: noise through a resonant band, pitch-swept. */
+  _impact(opts, { freq = 220, q = 4, dur = 0.22, level = 0.9, type = 'bandpass', sweep = 0.35, rev = 0.25, at = 0 }) {
+    const ctx = this.ctx, t = this._now() + at;
