+      this._env(g, t, 0.002, dur * (1 - i * 0.13), 0.6 / (i + 1));
+      o.connect(g); g.connect(out);
+      o.start(t);
+      o.stop(t + dur + 0.1);
+    }
+  }
+
+  /** Air movement: filtered noise with a slow swell. */
