+  }
+
+  // --- movement ----------------------------------------------------------
+  _sfx_step(o) {
+    // Per-ACTOR throttle. A global 'step' key meant that with three actors
+    // moving, two of every three footsteps were silently discarded — the whole
+    // crowd shared one 90 ms budget.
