+      this._impact(o, {
+        freq: cfg.body * this.rng.range(0.9, 1.1), q: 1.1, dur: cfg.dur * 1.6,
+        level: lv * 0.55, type: 'lowpass', sweep: 0.5, rev: cfg.rev ?? 0.15,
+      });
+    }
+  }
